#!/usr/bin/env node
// Generates the web client's part catalog from content/parts.json.
// The client bundles a byte-faithful copy of the server content document so the
// offline slope builder and the palette render exactly what the server serves;
// this generator keeps the copy in lockstep instead of hand-maintaining a table.
//
// Usage:
//   node tools/web-parts/generate-play-parts.mjs          # write the generated files
//   node tools/web-parts/generate-play-parts.mjs --check  # exit 1 if stale, write nothing

import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join, relative, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const HERE = dirname(fileURLToPath(import.meta.url));
const REPO = resolve(HERE, "..", "..");
const SOURCE = join(REPO, "content", "parts.json");
const OUT_DIR = join(REPO, "clients", "web", "src", "builder");
const CHECK = process.argv.includes("--check");

if (!existsSync(SOURCE)) {
  console.error(`content document not found: ${SOURCE}`);
  process.exit(1);
}

const document = JSON.parse(readFileSync(SOURCE, "utf8"));
if (!Array.isArray(document.parts)) {
  console.error(`${SOURCE} has no parts array.`);
  process.exit(1);
}

const outputs = [
  {
    path: join(OUT_DIR, "playParts.generated.json"),
    content: `${JSON.stringify(document, null, 2)}\n`,
  },
  {
    path: join(OUT_DIR, "playParts.generated.ts"),
    content: `// Generated by tools/web-parts/generate-play-parts.mjs — do not edit by hand.
import document from "./playParts.generated.json";
import type { PartContentDocument } from "@/schema/types";
export const PLAY_PARTS = document as unknown as PartContentDocument;
`,
  },
];

if (CHECK) {
  const stale = outputs.filter(
    (output) => !existsSync(output.path) || readFileSync(output.path, "utf8") !== output.content,
  );
  if (stale.length > 0) {
    for (const output of stale) {
      console.error(`stale: ${relative(REPO, output.path)}`);
    }
    console.error("run: node tools/web-parts/generate-play-parts.mjs");
    process.exit(1);
  }
} else {
  for (const output of outputs) {
    writeFileSync(output.path, output.content);
  }
}

console.log(`parts: ${document.parts.length}`);
